/*
<Group description="Fundo e Cores Base" selector="body">
  <Variable name="body.background" description="Fundo Geral" type="background" color="#f8fafc" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>
  <Variable name="main.color" description="Cor Principal" type="color" default="#6366f1" value="#6366f1"/>
  <Variable name="theme.text" description="Cor do Texto" type="color" default="#1e293b" value="#1e293b"/>
  <Variable name="header.bg" description="Fundo do Cabeçalho" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="footer.bg" description="Fundo do Rodapé" type="color" default="#1e293b" value="#1e293b"/>
</Group>
<Group description="Tipografia" selector="body">
  <Variable name="body.font" description="Fonte do Texto" type="font" default="normal normal 16px system-ui,-apple-system,sans-serif" value="normal normal 16px system-ui,-apple-system,sans-serif"/>
</Group>
*/

:root {
  --sl-bg-body:        $(body.background);
  --sl-text-main:      $(theme.text);
  --sl-primary:        $(main.color);
  --sl-card-bg:        #ffffff;
  --sl-footer-bg:      #1e293b;
  --sl-radius-lg:      14px;
  --sl-radius-sm:      7px;
  --sl-transition:     all 0.3s cubic-bezier(0.4,0,0.2,1);
  --sl-btn-radius:     8px;
  --sl-btn-shadow:     0 2px 6px rgba(0,0,0,0.15);
  --sl-font-family:    system-ui,-apple-system,sans-serif;
  --sl-heading-weight: 700;
}

[[DYNAMIC_CSS]]

body {
  background-color: var(--sl-bg-body,#f8fafc);
  color: var(--sl-text-main);
  font-family: var(--sl-font-family,system-ui,sans-serif);
  margin:0; padding:0; overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}
img { max-width:100%; height:auto; display:block; }
a { color:var(--sl-primary); text-decoration:none; transition:var(--sl-transition); }
a:hover { filter:brightness(0.85); }
h1,h2,h3,h4,h5,h6 { font-weight:var(--sl-heading-weight); }

/* ── HEADER ─────────────────────────────────────────── */
/* Wrapper .site-header (não .sl-header) — classe real de
   exemplos/appstore-bulma-mobile.xml (achado, mesma correção já
   aplicada em noticias-mag-news: .sl-header só fazia sentido enquanto
   o nicho usava o chassis compartilhado). .sl-header-brand mantida —
   classe real do token HEADER_WIDGET genérico (gerarHeaderWidget(),
   widgets.js), nunca .mag-header-content ou similar. */
.site-header {
  background: var(--sl-card-bg);
  border-bottom: 1px solid rgba(0,0,0,0.07);
  padding: .875rem 0;
}
.sl-header-brand { font-size:1.4rem; font-weight:800; color:var(--sl-text-main); letter-spacing:-.02em; }
.sl-header-brand:hover { color:var(--sl-primary); filter:none; }
.site-header-search { max-width:260px; }
@media (max-width:575.98px) { .site-header-search { display:none !important; } }

/* ── NAV ─────────────────────────────────────────────── */
.sl-nav {
  background: var(--sl-primary);
  padding: 0;
}
.sl-nav ul { list-style:none; padding:0; margin:0; display:flex; flex-wrap:wrap; }
.sl-nav ul li { position:relative; }
.sl-nav ul li a {
  display:block; padding:10px 16px;
  color:rgba(255,255,255,0.9); font-size:.875rem; font-weight:600;
  transition:var(--sl-transition);
}
.sl-nav ul li a:hover { background:rgba(0,0,0,0.15); color:#fff; filter:none; }
.sl-nav ul ul {
  position:absolute; top:100%; left:0; display:none;
  background:var(--sl-card-bg); min-width:200px;
  box-shadow:0 10px 25px rgba(0,0,0,0.15); z-index:99;
  border-radius:0 0 var(--sl-radius-sm) var(--sl-radius-sm);
}
.sl-nav ul ul li a { color:var(--sl-text-main); padding:9px 16px; }
.sl-nav ul ul li a:hover { background:color-mix(in srgb,var(--sl-primary) 8%,transparent); color:var(--sl-primary); }
.sl-nav ul li:hover > ul { display:block; }
@media (max-width:768px) {
  .sl-nav ul ul { position:static; box-shadow:none; background:rgba(0,0,0,0.15); }
  .sl-nav ul ul li a { color:rgba(255,255,255,.9); }
}

/* ── SWIPE CATEGORIES (real: seção própria 'swipe-categories') ────── */
.swipe-menu-container {
  display: flex; overflow-x: auto; gap: 0.75rem; padding: .75rem 0;
  scrollbar-width: none;
}
.swipe-menu-container::-webkit-scrollbar { display: none; }
.swipe-menu-item {
  white-space: nowrap; background: var(--sl-card-bg); border: 1px solid rgba(0,0,0,0.1);
  border-radius: 50px; padding: 0.4rem 1.2rem; color: var(--sl-text-main);
  font-weight: 600; font-size: 0.85rem; text-decoration: none; transition: var(--sl-transition);
}
.swipe-menu-item:hover, .swipe-menu-item.active {
  background: var(--sl-primary); color: #ffffff; border-color: var(--sl-primary); filter: none;
}

/* Cards do feed antigo (post-destacado + grid, layout herdado do
   chassis genérico) removidos aqui (achado 8) — nunca existiram no
   arquivo real. A listagem de posts real usa app-list-card (CSS
   própria na peça app-list-card-style do dossiê) — lista chata, sem
   post-destacado nem grid. */

/* ── SIDEBAR WIDGETS ─────────────────────────────────── */
.blog-widget {
  background: var(--sl-card-bg);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: var(--sl-radius-lg);
  overflow: hidden;
  margin-bottom: 1.5rem;
}
.blog-widget-header {
  padding: 12px 16px;
  font-weight: 800;
  font-size: .75rem;
  text-transform: uppercase;
  letter-spacing: .09em;
  border-bottom: 1px solid rgba(0,0,0,0.06);
  display: flex; align-items:center; gap:8px;
}
.blog-widget-header::before { content:''; width:3px; height:14px; background:var(--sl-primary); border-radius:2px; }
.blog-widget-body { padding:14px 16px; }

/* Popular posts list */
.blog-popular-list { list-style:none; padding:0; margin:0; }
.blog-popular-list li {
  display:flex; gap:10px; align-items:center;
  padding:9px 0;
  border-bottom:1px solid rgba(0,0,0,0.05);
}
.blog-popular-list li:last-child { border-bottom:none; }
.blog-popular-list .blog-pop-thumb {
  width:56px; height:42px; flex-shrink:0;
  border-radius:var(--sl-radius-sm); overflow:hidden;
}
.blog-popular-list .blog-pop-thumb img { width:100%; height:100%; object-fit:cover; }
.blog-popular-list a { color:var(--sl-text-main); font-size:.82rem; font-weight:600; line-height:1.3; }
.blog-popular-list a:hover { color:var(--sl-primary); filter:none; }

/* Label pills */
.sl-label-widget ul { padding:0; margin:0; list-style:none; display:flex; flex-wrap:wrap; gap:7px; }
.sl-label-list a {
  display:inline-block; padding:5px 13px;
  background:color-mix(in srgb,var(--sl-primary) 10%,transparent);
  color:var(--sl-primary); border-radius:50px;
  font-size:.8rem; font-weight:700; transition:var(--sl-transition);
}
.sl-label-list a:hover { background:var(--sl-primary); color:#fff; filter:none; }
.sl-label-cloud a {
  display:inline-block; padding:4px 12px;
  border:1px solid var(--sl-primary); color:var(--sl-text-main);
  border-radius:var(--sl-radius-lg); font-size:.88rem; transition:var(--sl-transition);
}
.sl-label-cloud a:hover { background:var(--sl-primary); color:#fff; transform:translateY(-2px); filter:none; }

/* ── AUTO-TOC (single post sidebar) ─────────────────── */
.blog-toc-widget { position:sticky; top:16px; }
.blog-toc-list { list-style:none; padding:0; margin:0; }
.blog-toc-list li { border-left:2px solid rgba(0,0,0,0.08); padding:.25rem 0 .25rem .75rem; transition:border-color .2s; }
.blog-toc-list li.active { border-left-color:var(--sl-primary); }
.blog-toc-list li.toc-h3 { padding-left:1.25rem; font-size:.8rem; }
.blog-toc-list a { color:#64748b; font-size:.83rem; line-height:1.4; display:block; }
.blog-toc-list a:hover,.blog-toc-list li.active a { color:var(--sl-primary); filter:none; }

/* ── SINGLE POST TYPOGRAPHY ──────────────────────────── */
/* Imagem hero separada, meta bar, author box e relacionados do post
   único (layout antigo herdado do chassis genérico) removidos aqui
   (achado 8): a view de post único real
   (exemplos/appstore-bulma-mobile.xml) é minimalista — h1 (só em
   Page) + corpo em post-content, sem nenhum desses elementos.
   Tipografia do corpo mantida (não é estrutura de chassis, é
   legibilidade de conteúdo), só retargetada pra classe real
   post-content. Blockquote específico vem da peça blockquote-appstore
   do dossiê, corrigida pra alvejar o seletor real também. */
.post-content { font-size:1.06rem; line-height:1.85; }
.post-content h2 { margin-top:2.5rem; padding-bottom:.5rem; border-bottom:2px solid rgba(0,0,0,0.07); }
.post-content h3 { margin-top:2rem; }
.post-content p { margin-bottom:1.4rem; }
.post-content img { border-radius:var(--sl-radius-sm); margin:1rem auto; }
.post-content a { text-decoration:underline; text-decoration-color:color-mix(in srgb,var(--sl-primary) 50%,transparent); text-underline-offset:3px; }
.post-content iframe,.post-content object,.post-content embed { max-width:100%; }
.sl-share-buttons a.btn { flex-shrink:0; }

/* ── BUTTONS ──────────────────────────────────────────── */
.btn-primary,.btn-outline-primary { border-radius:var(--sl-btn-radius); box-shadow:var(--sl-btn-shadow); }
.btn-outline-primary { color:var(--sl-primary); border-color:var(--sl-primary); }
.btn-outline-primary:hover,.btn-outline-primary:focus,.btn-outline-primary:active,.btn-outline-primary.active {
  background-color:var(--sl-primary); border-color:var(--sl-primary); color:#fff; filter:none;
}

/* ── FOOTER ───────────────────────────────────────────── */
/* Wrapper .site-footer (não .sl-footer) — classe real do arquivo,
   mesmo achado do header acima. --sl-footer-bg (variável, não classe)
   mantida — token global compartilhado entre nichos. */
.site-footer { background:var(--sl-footer-bg,#1e293b); color:#94a3b8; }
.site-footer h6 { color:#f1f5f9; font-weight:700; text-transform:uppercase; letter-spacing:.06em; font-size:.75rem; margin-bottom:1rem; }
.site-footer a { color:#94a3b8; font-size:.875rem; }
.site-footer a:hover { color:#f1f5f9; filter:none; }
.site-footer-divider { border-color:rgba(255,255,255,0.08) !important; }

/* ── DARK MODE ────────────────────────────────────────── */
[data-bs-theme="dark"] body { background-color:#0d1117; color:#e2e8f0; }
[data-bs-theme="dark"] .site-header { background:#161c2d; border-bottom-color:rgba(255,255,255,0.07); }
[data-bs-theme="dark"] .sl-header-brand { color:#e2e8f0; }
[data-bs-theme="dark"] .blog-widget { background:#1e2535; border-color:rgba(255,255,255,0.06); }
[data-bs-theme="dark"] .blog-popular-list li { border-bottom-color:rgba(255,255,255,0.06); }
[data-bs-theme="dark"] .blog-toc-list li { border-left-color:rgba(255,255,255,0.1); }
[data-bs-theme="dark"] .post-content h2 { border-bottom-color:rgba(255,255,255,0.08); }
[data-bs-theme="dark"] .blog-post-article { background:#1e2535 !important; }
[data-bs-theme="dark"] .blog-widget-header { background:rgba(255,255,255,0.04); border-bottom-color:rgba(255,255,255,0.07); }
[data-bs-theme="dark"] .app-list-card { background:#1e2535 !important; border-color:rgba(255,255,255,0.06) !important; }

/* ── RESPONSIVE ────────────────────────────────────────── */
@media (max-width:575.98px) {
  .post-content { font-size:.97rem; }
}

/* GRID LAYOUTS (lista/dupla/revista/quadrado/mural/coluna-unica/zigzag) —
   centralizado em gerarGridCardCss() (designTokensCss.js), injetado via
   DYNAMIC_CSS. */

/* === CSS DO NICHO ===================================== */
[[NICHO_CSS]]
